head.script:
scwin.checkHolder = function() {
    if (WebSquare.wUnit.getJq("#wq_uuid_3").attr("placeholder")) {
        return WebSquare.wUnit.getJq("#wq_uuid_3").attr("placeholder") == "teset";
    }
    if (WebSquare.wUnit.getJq("#wq_uuid_3").hasClass("w2textarea_placeholder")) {
        return true;
    }
    return false;
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. Source 탭에서 Textarea 에 placeholder 가 있는지 확인한다.
    //1. In the Source tab, make sure there is a placeholder in the Textarea.
    //Verify step 1. placeholder = "teset"
    //Test step 2. 브라우저에서 Textarea 를 확인한다.
    //2. Check the Textarea in your browser.
    //Verify step 2. Textarea is displayed with teset.
    WebSquare.wUnit.addCommand("assert", "scwin.checkHolder()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 01-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
